// Regenerates one Code Connect template per Lemonade icon.
//
//   node scripts/generate-icon-templates.mjs
//
// Reads icons.manifest.json (kebab-case Figma name -> node id, refreshed from
// Figma) and cross-checks every entry against the LemonadeIcons enum, which is
// itself generated by svg-asset-converter.main.kts. If the two ever drift the
// script fails rather than emitting templates that point at icons the enum does
// not have.

import { readFileSync, writeFileSync, mkdirSync, rmSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const repo = join(root, '..')

const ENUM_PATH = 'kmp/core/src/commonMain/kotlin/com/teya/lemonade/core/LemonadeIcons.kt'
const OUT_DIR = join(root, 'connect', 'icons')

const manifest = JSON.parse(readFileSync(join(root, 'icons.manifest.json'), 'utf8'))
const enumSource = readFileSync(join(repo, ENUM_PATH), 'utf8')
const enumEntries = new Set([...enumSource.matchAll(/^\s+([A-Z][A-Za-z0-9]*),/gm)].map((m) => m[1]))

const pascal = (name) =>
  name
    .split(/[-_ ]+/)
    .filter(Boolean)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('')

const missing = Object.keys(manifest.icons).filter((name) => !enumEntries.has(pascal(name)))
if (missing.length) {
  console.error(`${missing.length} Figma icon(s) have no LemonadeIcons entry:`)
  for (const name of missing) console.error(`  ${name} -> ${pascal(name)}`)
  console.error('\nRun the svg-asset-converter, or refresh icons.manifest.json from Figma.')
  process.exit(1)
}

rmSync(OUT_DIR, { recursive: true, force: true })
mkdirSync(OUT_DIR, { recursive: true })

for (const [name, nodeId] of Object.entries(manifest.icons)) {
  const entry = pascal(name)
  // Emits the bare enum value, not a composable call: every consumer of an icon
  // (Button.icon, Tag.icon, IconButton.icon) takes LemonadeIcons. Parents that
  // need a composable wrap this in LemonadeUi.Icon themselves.
  const file = `// url=<LEMONADE_ICONS>?node-id=${nodeId.replace(':', '-')}
// source=${ENUM_PATH}
// component=LemonadeIcons
import figma from 'figma'

export default {
  example: figma.kotlin\`LemonadeIcons.${entry}\`,
  imports: ['import com.teya.lemonade.core.LemonadeIcons'],
  id: 'icon-${name}',
  metadata: { nestable: true },
}
`
  writeFileSync(join(OUT_DIR, `${entry}.figma.ts`), file)
}

console.log(`Generated ${readdirSync(OUT_DIR).length} icon templates in connect/icons/`)
